package glitch

import data.glitch_lib

is_conditional_with_multiple_branches(cond) {
    cond.ir_type == "ConditionalStatement"
    cond.else_statement != null
    cond.else_statement.condition != null
}

has_else_branch(cond) {
    cond.ir_type == "ConditionalStatement"
    cond.else_statement != null
    cond.else_statement.condition == null
}

has_switch_type(cond) {
    cond.ir_type == "ConditionalStatement"
    cond.type == "SWITCH"
}

count_conditional_branches(cond) = n {
    cond.ir_type == "ConditionalStatement"
    n := count_branches_recursive(cond, 0)
}

count_branches_recursive(cond, acc) = n {
    cond.else_statement == null
    n := acc + 1
}

count_branches_recursive(cond, acc) = n {
    cond.else_statement != null
    cond.else_statement.condition != null
    n := count_branches_recursive(cond.else_statement, acc + 1)
}

count_branches_recursive(cond, acc) = n {
    cond.else_statement != null
    cond.else_statement.condition == null
    n := acc + 1
}

is_hash_lookup_without_default(node) {
    node.ir_type == "FunctionCall"
    node.name == "lookup"
    count(node.args) < 3
}

is_map_with_partial_coverage(node) {
    node.ir_type == "Hash"
    some key
    walk(node.value, [_, key])
    key.ir_type == "VariableReference"
}

is_environment_routing_pattern(cond) {
    cond.condition.ir_type == "Equal"
    is_environment_comparison(cond.condition)
}

is_environment_comparison(eq) {
    eq.left.ir_type == "VariableReference"
    is_environment_string(eq.right)
}

is_environment_comparison(eq) {
    eq.right.ir_type == "VariableReference"
    is_environment_string(eq.left)
}

is_environment_string(node) {
    node.ir_type == "String"
    regex.match("(?i)^(prod|dev|staging|test|uat|qa|production|development)$", node.value)
}

is_region_routing_pattern(cond) {
    cond.condition.ir_type == "Equal"
    is_region_comparison(cond.condition)
}

is_region_comparison(eq) {
    eq.left.ir_type == "VariableReference"
    is_region_string(eq.right)
}

is_region_comparison(eq) {
    eq.right.ir_type == "VariableReference"
    is_region_string(eq.left)
}

is_region_string(node) {
    node.ir_type == "String"
    regex.match("^[a-z]{2}-[a-z]+-[0-9]+$", node.value)
}

is_security_level_pattern(cond) {
    cond.condition.ir_type == "Equal"
    is_security_comparison(cond.condition)
}

is_security_comparison(eq) {
    is_security_level_string(eq.left)
}

is_security_comparison(eq) {
    is_security_level_string(eq.right)
}

is_security_level_string(node) {
    node.ir_type == "String"
    regex.match("(?i)^(high|medium|low|none|disabled|enabled|true|false)$", node.value)
}

is_boolean_driven_conditional(cond) {
    cond.condition.ir_type == "Boolean"
}

has_unbounded_input_in_condition(cond) {
    walk(cond.condition, [_, n])
    n.ir_type == "VariableReference"
}

has_variable_reference_in_condition(cond) {
    walk(cond.condition, [_, n])
    n.ir_type == "VariableReference"
}

find_conditional_statements_in_node(node) = conds {
    conds := {n |
        walk(node, [_, n])
        n.ir_type == "ConditionalStatement"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    conds := find_conditional_statements_in_node(parent)
    cond := conds[_]

    is_conditional_with_multiple_branches(cond)
    not has_else_branch(cond)

    result := {
        "type": "sec_no_default_switch",
